package org.springframework.samples.petclinic.rest.function.owner;

import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;

/**
 * Normalizes the optional {@code email} of an owner request. Email is optional: a null or blank
 * value is left untouched (no email). When present it must be a syntactically valid address,
 * otherwise the request is rejected with a 400 via {@link InvalidEmailException}. A valid address is
 * mutated in place (via {@code @Val}) to its lower-cased form, so the stored and returned
 * {@code email} is lower-case. Runs before {@link BuildOwner}/{@code ApplyOwner}.
 */
public class NormalizeOwnerEmail {

    /** A pragmatic single-address check: local part, '@', domain with at least one dot, no spaces. */
    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
        String email = request.getEmail();
        if (email == null || email.isBlank()) {
            return; // email is optional
        }
        String trimmed = email.trim();
        if (!EMAIL.matcher(trimmed).matches()) {
            throw new InvalidEmailException(email);
        }
        request.setEmail(trimmed.toLowerCase());
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.CityRegion;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;

/**
 * Validates the owner's {@code postcode} WHEN PRESENT, so an owner created without a postcode stays
 * accepted (the request contract is backward-compatible). A supplied postcode must be exactly four
 * digits and, when the city has a known region, must fall within that region's fixed range
 * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
 * postcode. Anything else is rejected with 400 via {@link InvalidPostcodeException}.
 *
 * <p>Reads the body published by the preceding validate step via {@code @Val}, so it runs before the
 * owner is built/loaded and an invalid postcode is a 400 rather than being masked by a later step.
 */
public class ValidateOwnerPostcode {

    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
        String postcode = request.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return; // optional when absent
        }
        String city = request.getCity();
        if (!postcode.matches("[0-9]{4}")) {
            throw new InvalidPostcodeException(postcode, city, "must be exactly four digits");
        }
        int[] range = CityRegion.postcodeRange(city);
        if (range == null) {
            return; // no known region for this city; any 4-digit postcode is valid
        }
        int value = Integer.parseInt(postcode);
        if (value < range[0] || value > range[1]) {
            throw new InvalidPostcodeException(postcode, city,
                    "out of range " + range[0] + "-" + range[1] + " for the city's region");
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;

/**
 * Validates the owner's {@code registrationDate} WHEN SUPPLIED, so a request that omits one stays
 * accepted (the server defaults it in {@link ResolveRegistrationDate}). A supplied date must not be
 * later than the server's current date; a future date is rejected with 400 via
 * {@link FutureRegistrationDateException}.
 *
 * <p>Reads the body published by the preceding validate step via {@code @Val} and runs before the
 * date is resolved/defaulted, so a future date is a 400 rather than being masked by a later step.
 */
public class ValidateRegistrationDate {

    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
        LocalDate supplied = request.getRegistrationDate();
        if (supplied == null) {
            return; // optional when absent; the server defaults it later
        }
        LocalDate serverDate = LocalDate.now();
        if (supplied.isAfter(serverDate)) {
            throw new FutureRegistrationDateException(supplied, serverDate);
        }
    }
}

